css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader .cloud { position: absolute; top: 22%; left: 50%; width: 56%; height: 22%; margin-left: -28%; background: linear-gradient(#f1f5f9, #94a3b8); border-radius: 40px; }
.loader .cloud::before { content: ''; position: absolute; bottom: 0; left: 12%; width: 42%; height: 150%; background: inherit; border-radius: 50%; }
.loader .cloud::after { content: ''; position: absolute; bottom: 0; right: 10%; width: 50%; height: 130%; background: inherit; border-radius: 50%; }
.loader span { position: absolute; top: 52%; width: calc(var(--loader-size) * .04); height: calc(var(--loader-size) * .13); border-radius: 0 0 4px 4px; background: var(--accent); animation: drop calc(var(--loader-speed) * 1) linear infinite; }
.loader span:nth-child(even) { background: var(--accent-2); }
.loader span:nth-child(1) { left: 32%; animation-delay: 0s; }
.loader span:nth-child(2) { left: 46%; animation-delay: calc(var(--loader-speed) * .35); }
.loader span:nth-child(3) { left: 60%; animation-delay: calc(var(--loader-speed) * .15); }
.loader span:nth-child(4) { left: 68%; animation-delay: calc(var(--loader-speed) * .55); }
@keyframes drop { 0% { transform: translateY(0); opacity: 0; } 20% { opacity: 1; } 100% { transform: translateY(140%); opacity: 0; } }
